SINA_SMART["anat1-upper-skeleton"] = {"lecture":"anat1-upper-skeleton","title":"The skeleton of the upper limb","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat1-upper-skeleton:e0","text":"Upper limb: shoulder, arm, forearm, hand.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-upper-skeleton:e1","text":"Shoulder girdle: clavicle + scapula.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-upper-skeleton:e2","text":"Clavicle: pectoralis major and deltoid (anterior), SCM and trapezius (posterior).","topic":"Clavicle and scapula","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-upper-skeleton:e3","text":"Scapula: spine → acromion; supra-/infraspinous fossae; coracoid; glenoid.","topic":"Clavicle and scapula","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-upper-skeleton:e4","text":"Supraglenoid tubercle: long head of biceps; infraglenoid: long head of triceps.","topic":"Clavicle and scapula","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-upper-skeleton:e5","text":"Humerus: greater tubercle (SS, IS, TMi), lesser tubercle (subscapularis).","topic":"Humerus","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-upper-skeleton:e6","text":"Radial groove carries the radial nerve.","topic":"Humerus","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-upper-skeleton:e7","text":"Capitulum ↔ radius; trochlea ↔ ulna; medial epicondyle = flexors, lateral = extensors.","topic":"Humerus","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-upper-skeleton:e8","text":"Radial tuberosity: biceps; radial styloid: brachioradialis.","topic":"Forearm and hand","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-upper-skeleton:e9","text":"Hand: 8 carpals, 5 metacarpals, 14 phalanges.","topic":"Forearm and hand","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"nh8yvs":"a","18xwpgr":"a","1ls9dxz":"a","ermums":"a","11b6h26":"a","doukxp":"a","103x08b":"a","1brch6a":"a","24flu4":"a","17sxx80":"a","1gckp66":"a","ojmzp":"a","1xdddou":"a","nt0s8n":"a"},"mapCounts":{"verified":0,"auto":14,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat1-upper-skeleton:e0":{"s":0,"u":["Upper limb: shoulder, arm, forearm, hand.","The upper (thoracic) limb has four segments: shoulder, arm, forearm and hand ."],"dp":[]},"anat1-upper-skeleton:e1":{"s":0,"u":["Shoulder girdle: clavicle + scapula.","The shoulder (pectoral) girdle , made of the clavicle and scapula , connects it to the thorax."],"dp":[]},"anat1-upper-skeleton:e2":{"s":1,"u":["Clavicle: pectoralis major and deltoid (anterior), SCM and trapezius (posterior).","Anterior border: pectoralis major (medial two-thirds) and deltoid (lateral third); posterior border: sternocleidomastoid (medially) and trapezius (laterally).","Posterior surface divided by the spine into supraspinous (supraspinatus) and infraspinous (infraspinatus) fossae; the spine ends in the acromion (articulates with the clavicle; trapezius and deltoid)."],"dp":[]},"anat1-upper-skeleton:e3":{"s":1,"u":["Scapula: spine → acromion; supra-/infraspinous fossae; coracoid; glenoid.","Posterior surface divided by the spine into supraspinous (supraspinatus) and infraspinous (infraspinatus) fossae; the spine ends in the acromion (articulates with the clavicle; trapezius and deltoid)."],"dp":[]},"anat1-upper-skeleton:e4":{"s":1,"u":["Supraglenoid tubercle: long head of biceps; infraglenoid: long head of triceps.","Angles: superomedial (levator scapulae), inferior (latissimus dorsi), superolateral with the glenoid cavity (humeral head), flanked by the supraglenoid (long head of biceps) and infraglenoid (long head of triceps) tubercles."],"dp":[{"h":"Note","t":"Supraglenoid tubercle = long head of biceps ; infraglenoid = long head of triceps . Coracoid = pectoralis minor, coracobrachialis, short head of biceps."}]},"anat1-upper-skeleton:e5":{"s":2,"u":["Humerus: greater tubercle (SS, IS, TMi), lesser tubercle (subscapularis).","Proximal end: head (glenoid), anatomical neck, lesser tubercle (subscapularis), greater tubercle (supraspinatus, infraspinatus, teres minor from top to bottom), intertubercular (bicipital) groove (long head of biceps), with pectoralis major, latissimus dorsi and teres major inserting around it."],"dp":[{"h":"Memory aid","t":"Rotator cuff 'SITS' : Supraspinatus, Infraspinatus, Teres minor on the greater tubercle (top to bottom); Subscapularis on the lesser tubercle ."}]},"anat1-upper-skeleton:e6":{"s":2,"u":["Radial groove carries the radial nerve.","Shaft with the radial groove (radial nerve and deep brachial vessels), the deltoid tuberosity ('V' of the deltoid), coracobrachialis medially, triceps lateral head above and medial head below the groove."],"dp":[{"h":"Why a humeral shaft fracture can cause wrist drop","t":"The radial nerve winds around the back of the humerus in the radial groove, directly on the bone. A mid-shaft fracture can stretch or cut it, paralysing the wrist and finger extensors, so the hand hangs limply: wrist drop. Checking wrist extension is part of examining any humeral fracture. Source: the lecture's description of the radial groove."},{"h":"Clinical","t":"Nerves at risk with humeral fractures : surgical neck → axillary ; mid-shaft (radial groove) → radial (wrist drop); medial epicondyle → ulnar ; supracondylar → median and brachial artery."}]},"anat1-upper-skeleton:e7":{"s":2,"u":["Capitulum ↔ radius; trochlea ↔ ulna; medial epicondyle = flexors, lateral = extensors.","Distal end: capitulum (radius), trochlea (ulna), lateral epicondyle (extensors), medial epicondyle (flexors), olecranon fossa behind."],"dp":[{"h":"Note","t":"Humerus: capitulum ↔ radius , trochlea ↔ ulna ; medial epicondyle = flexors , lateral = extensors. Radial groove carries the radial nerve and profunda brachii."}]},"anat1-upper-skeleton:e8":{"s":3,"u":["Radial tuberosity: biceps; radial styloid: brachioradialis.","Radius: anterior face (flexor pollicis longus, pronator quadratus), lateral face (supinator, pronator teres), posterior face (supinator, abductor and extensor pollicis longus); head (capitulum and ulnar radial notch), neck, radial tuberosity (biceps tendon); distal end articulating with scaphoid and lunate, radial styloid (brachioradialis), ulnar notch."],"dp":[{"h":"Note","t":"The clavicle is the only long bone lying horizontally and the most commonly fractured; the fracture is usually at the junction of the middle and lateral thirds. Radial tuberosity = biceps; radial styloid = brachioradialis."}]},"anat1-upper-skeleton:e9":{"s":3,"u":["Hand: 8 carpals, 5 metacarpals, 14 phalanges.","Hand : 8 carpal bones in two rows (scaphoid, lunate, triquetrum, pisiform; trapezium, trapezoid, capitate, hamate), 5 metacarpals , 14 phalanges ."],"dp":[{"h":"Memory aid","t":"Carpals , lateral to medial, proximal then distal row: 'Some Lovers Try Positions That They Can't Handle' : Scaphoid, Lunate, Triquetrum, Pisiform, Trapezium, Trapezoid, Capitate, Hamate."},{"h":"Note","t":"Hand bones: 8 carpals, 5 metacarpals, 14 phalanges (the thumb has only two)."}]}},"meta":{"nh8yvs":{"a":"recall","vg":"anat1-upper-skeleton:e1/recall/1"},"18xwpgr":{"a":"recall","vg":"anat1-upper-skeleton:e3/recall/1"},"1ls9dxz":{"a":"recall","vg":"anat1-upper-skeleton:e2/recall/1"},"ermums":{"a":"recall","vg":"anat1-upper-skeleton:e3/recall/1"},"11b6h26":{"a":"recall","vg":"anat1-upper-skeleton:e4/recall/1"},"doukxp":{"a":"recall","vg":"anat1-upper-skeleton:e4/recall/2"},"103x08b":{"a":"recall","vg":"anat1-upper-skeleton:e5/recall/1"},"1brch6a":{"a":"recall","vg":"anat1-upper-skeleton:e4/recall/3"},"24flu4":{"a":"recall","vg":"anat1-upper-skeleton:e6/recall/1"},"17sxx80":{"a":"recall","vg":"anat1-upper-skeleton:e7/recall/1"},"1gckp66":{"a":"recall","vg":"anat1-upper-skeleton:e7/recall/2"},"ojmzp":{"a":"recall","vg":"anat1-upper-skeleton:e8/recall/1"},"1xdddou":{"a":"recall","vg":"anat1-upper-skeleton:e9/recall/1"},"nt0s8n":{"a":"recall","vg":"anat1-upper-skeleton:e7/recall/3"}},"explRev":"97bbf5f040e1"};
